import{_ as o,l,o as e,c as n,v as t,p as s,x as r,d,i as p,S as h}from"./chunks/framework.InCnrqk-.js";const E=JSON.parse('{"title":"在线算法与竞争比","description":"","frontmatter":{"title":"在线算法与竞争比","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/competitive-ratio.md","filePath":"cs/competitive-ratio.md","lastUpdated":1789023840000}'),c={name:"cs/competitive-ratio.md"};function m(_,a,u,f,T,P){const i=l("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="在线算法与竞争比" tabindex="-1">在线算法与竞争比 <a class="header-anchor" href="#在线算法与竞争比" aria-label="Permalink to &quot;在线算法与竞争比&quot;">​</a></h1><div class="epigraph"><p>输入一个个到来、决策不可悔；竞争比是算法代价与事后最优的最坏比，对手可自适应。</p><footer>—— 据 Sleator and Tarjan, Amortized Efficiency of List Update and Paging Rules, 1985；Borodin and El-Yaniv, Online Computation and Competitive Analysis 整理</footer></div><p>上一课<a href="/cs/random-walk-mixing">随机游走</a>假定图已知。在线：未来未知。主干摊还已会势能。缺口是竞争比 \\(\\mathrm{ALG}/\\mathrm{OPT}\\le\\rho\\)。不重写 Karger。后课分页、租买、秘书都是实例。不把限价簿当输入模型。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>离线 OPT 看见全序列。在线第 \\(t\\) 步只看见前 \\(t\\)。确定性在线常被对手压到下界。随机在线对 oblivious 对手可更好。势函数证竞争比：摊还代价 \\(\\le\\rho\\cdot\\) 一步 OPT。</p><p>缺口是定义，不是具体分页（下一课）。</p><h3 id="不是平均情形" tabindex="-1">不是平均情形 <a class="header-anchor" href="#不是平均情形" aria-label="Permalink to &quot;不是平均情形&quot;">​</a></h3><p>竞争比最坏序列。平均输入是另一模型。不要把「实践还行」当 \\(\\rho\\)。</p><p><span class="marginnote">Sleator–Tarjan 1985 列表更新与分页。Borodin–El-Yaniv 书。后课分页、ski-rental、秘书。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>先写离线最优结构。设计在线，势或不变量证 \\(\\rho\\)。给下界：对手策略。随机算法写清对手模型。</p>',11)),(e(),s(h,null,{default:r(()=>[p(i,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20IN%5B%22%E5%BA%8F%E5%88%97%E9%80%90%E9%A1%B9%22%5D%20--%3E%20ON%5B%22%E4%B8%8D%E5%8F%AF%E6%82%94%E5%86%B3%E7%AD%96%22%5D%0A%20%20ON%20--%3E%20RHO%5B%22ALG%20%E2%89%A4%20%CF%81%20OPT%20%2B%20O(1)%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>加性常数允许。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>势把未来债务记在数据结构状态上。对手论证后课专讲。与近似比：近似是离线多项式对 OPT；在线是信息缺失。与流算法：流可事后输出，在线必须即时行动。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写全部 k-server。不写预测增强在线。后课默认：在线质量用竞争比。下一课页面置换。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>竞争比 = 最坏 ALG/OPT。</li><li>势函数是主证法。</li><li>与离线近似、流模型不同。</li><li>出处：Sleator and Tarjan, 1985。</li></ul>',7))])}const b=o(c,[["render",m]]);export{E as __pageData,b as default};
